import{_ as t,a as r,c as e,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Go 面试复盘 · 面试快问快答 60 题","description":"在完成基础后，按语言机制、运行时、网络存储和项目证据复盘后端问题。","frontmatter":{"title":"Go 面试复盘 · 面试快问快答 60 题","description":"在完成基础后，按语言机制、运行时、网络存储和项目证据复盘后端问题。","splitFrom":"programming/go/pro/interview/golang-interview.md","showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"},{"id":"mysql","title":"MySQL","link":"/topics/mysql/"},{"id":"redis","title":"Redis","link":"/topics/redis/"},{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Go 后端面试复盘：语言、并发与服务实践","summary":"在完成基础后，按语言机制、运行时、网络存储和项目证据复盘后端问题。","status":"active","related":[{"title":"Go 后端面试复盘：语言、并发与服务实践","link":"/programming/go/pro/interview/golang-interview","kind":"排错","scope":"general","audience":"general"},{"title":"Go 面试复盘 · 并发、重试与 HTTP 模板","link":"/programming/go/pro/interview/golang-interview-part-16","kind":"排错","scope":"general","audience":"general"},{"title":"Go 面试复盘 · 测试、基准与性能诊断","link":"/programming/go/pro/interview/golang-interview-part-11","kind":"排错","scope":"general","audience":"general"},{"title":"Go 面试复盘 · 错误链与 goroutine 调度","link":"/programming/go/pro/interview/golang-interview-part-05","kind":"排错","scope":"general","audience":"general"},{"title":"Go 面试复盘 · 代码陷阱与错因自测","link":"/programming/go/pro/interview/golang-interview-part-14","kind":"排错","scope":"general","audience":"general"}],"prev":{"text":"Go 面试复盘 · 代码陷阱与错因自测","link":"/programming/go/pro/interview/golang-interview-part-14"},"next":{"text":"Go 面试复盘 · 并发、重试与 HTTP 模板","link":"/programming/go/pro/interview/golang-interview-part-16"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Go 面试复盘 · 代码陷阱与错因自测","link":"/programming/go/pro/interview/golang-interview-part-14"},"next":{"text":"Go 面试复盘 · 并发、重试与 HTTP 模板","link":"/programming/go/pro/interview/golang-interview-part-16"}},"headers":[],"relativePath":"programming/go/pro/interview/golang-interview-part-15.md","filePath":"programming/go/pro/interview/golang-interview-part-15.md"}'),d={name:"programming/go/pro/interview/golang-interview-part-15.md"};function n(s,a,l,o,m,p){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="go-面试复盘-·-面试快问快答-60-题" tabindex="-1">Go 面试复盘 · 面试快问快答 60 题 <a class="header-anchor" href="#go-面试复盘-·-面试快问快答-60-题" aria-label="Permalink to &quot;Go 面试复盘 · 面试快问快答 60 题&quot;">​</a></h1><p><a href="/programming/go/pro/interview/golang-interview">返回分篇目录</a></p><h2 id="_28-高频面试快问快答" tabindex="-1">28. 高频面试快问快答 <a class="header-anchor" href="#_28-高频面试快问快答" aria-label="Permalink to &quot;28. 高频面试快问快答 {#_28-高频面试快问快答}&quot;">​</a></h2><p>以下 60 道题按语言、容器、并发、内存、网络和工程分组。可以先做<a href="/programming/go/pro/review/review">四道机制自测</a>，再从错题所在的组开始。每题先口述答案并补出一个可能改变结论的条件，然后展开右栏核对，按链接回到原理或例子。</p><h3 id="_28-1-基础类" tabindex="-1">28.1 基础类 <a class="header-anchor" href="#_28-1-基础类" aria-label="Permalink to &quot;28.1 基础类 {#_28-1-基础类}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自测问题</th><th>回看或补充答案</th></tr></thead><tbody><tr><td><span id="q1-go-为什么不支持方法重载"></span>Q1：Go 为什么不支持方法重载？</td><td><details><summary aria-label="核对第 1 题">核对</summary>强调简单、明确和快速编译。不同语义使用不同函数名，或通过接口、泛型和可选配置表达。</details></td></tr><tr><td><span id="q2-go-是否支持默认参数"></span>Q2：Go 是否支持默认参数？</td><td><details><summary aria-label="核对第 2 题">核对</summary>不支持。常见替代方案是配置结构体、functional options 或提供多个命名清晰的构造函数。</details></td></tr><tr><td><span id="q3-go-是否支持三元运算符"></span>Q3：Go 是否支持三元运算符？</td><td><details><summary aria-label="核对第 3 题">核对</summary>不支持，使用 if/else，避免复杂表达式降低可读性。</details></td></tr><tr><td><span id="q4-可导出标识符规则是什么"></span>Q4：可导出标识符规则是什么？</td><td><details><summary aria-label="核对第 4 题">核对</summary>包作用域中的声明、字段名或方法名以 Unicode 大写字母开头时可导出。函数内局部变量即使首字母大写也只在其作用域内可见。</details></td></tr><tr><td><span id="q5-init-能被调用吗"></span>Q5：<code>init</code> 能被调用吗？</td><td><details><summary aria-label="核对第 5 题">核对</summary>不能显式调用，也不能引用。它由运行时在包初始化阶段执行。 <a href="/programming/go/pro/interview/golang-interview-part-01#_1-11-包级变量和-init-的初始化顺序是什么">初始化规则</a></details></td></tr><tr><td><span id="q6-一个包可以有多个-init-吗"></span>Q6：一个包可以有多个 init 吗？</td><td><details><summary aria-label="核对第 6 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-01#_1-11-包级变量和-init-的初始化顺序是什么">多个 init 的边界</a></details></td></tr><tr><td><span id="q7-main-包必须有什么"></span>Q7：main 包必须有什么？</td><td><details><summary aria-label="核对第 7 题">核对</summary>可执行程序入口需要 <code>package main</code> 和无参数、无返回值的 <code>func main()</code>。</details></td></tr><tr><td><span id="q8-空白标识符-有什么用途"></span>Q8：空白标识符 <code>_</code> 有什么用途？</td><td><details><summary aria-label="核对第 8 题">核对</summary>忽略值、仅触发包初始化的匿名导入、编译期接口检查等。匿名导入要有明确副作用理由。</details></td></tr><tr><td><span id="q9-go-中枚举怎么实现"></span>Q9：Go 中枚举怎么实现？</td><td><details><summary aria-label="核对第 9 题">核对</summary>通常使用自定义整数类型加 const/iota，并提供 String、Validate 等方法。对外协议值最好显式固定。 <a href="/programming/go/pro/interview/golang-interview-part-01#_1-8-iota-是什么">枚举与协议值</a></details></td></tr><tr><td><span id="q10-为什么不建议大量使用全局变量"></span>Q10：为什么不建议大量使用全局变量？</td><td><details><summary aria-label="核对第 10 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-12#_23-5-依赖注入有哪些方式">显式依赖与构造</a></details></td></tr></tbody></table><h3 id="_28-2-slice、map、interface" tabindex="-1">28.2 slice、map、interface <a class="header-anchor" href="#_28-2-slice、map、interface" aria-label="Permalink to &quot;28.2 slice、map、interface {#_28-2-slice、map、interface}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自测问题</th><th>回看或补充答案</th></tr></thead><tbody><tr><td><span id="q11-切片扩容后原切片会变化吗"></span>Q11：切片扩容后原切片会变化吗？</td><td><details><summary aria-label="核对第 11 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-02#_2-4-append-一定会分配新数组吗">append 返回值</a></details></td></tr><tr><td><span id="q12-切片作为函数参数能修改元素吗"></span>Q12：切片作为函数参数能修改元素吗？</td><td><details><summary aria-label="核对第 12 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-01#_1-4-go-中值类型和引用语义如何理解">切片传值与共享</a></details></td></tr><tr><td><span id="q13-copy-是深拷贝吗"></span>Q13：<code>copy</code> 是深拷贝吗？</td><td><details><summary aria-label="核对第 13 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-02#_2-6-如何正确复制-slice">浅拷贝边界</a></details></td></tr><tr><td><span id="q14-map-能边遍历边删除吗"></span>Q14：map 能边遍历边删除吗？</td><td><details><summary aria-label="核对第 14 题">核对</summary>同一 goroutine 在遍历期间删除尚未访问的项，该项此次不会再产生。新增项可能出现也可能跳过。其他 goroutine 并发修改仍需同步。</details></td></tr><tr><td><span id="q15-map-预分配容量是精确桶数量吗"></span>Q15：map 预分配容量是精确桶数量吗？</td><td><details><summary aria-label="核对第 15 题">核对</summary>不是。hint 只是预计元素数量，运行时据此优化初始分配。 <a href="/programming/go/pro/interview/golang-interview-part-07#_13-7-如何预分配">容量提示</a></details></td></tr><tr><td><span id="q16-接口越大越好吗"></span>Q16：接口越大越好吗？</td><td><details><summary aria-label="核对第 16 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-04#_5-1-go-接口的核心特点是什么">小接口原则</a></details></td></tr><tr><td><span id="q17-接口应该由实现方还是使用方定义"></span>Q17：接口应该由实现方还是使用方定义？</td><td><details><summary aria-label="核对第 17 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-04#_5-1-go-接口的核心特点是什么">使用方定义接口</a></details></td></tr><tr><td><span id="q18-reflect-deepequal-有什么问题"></span>Q18：<code>reflect.DeepEqual</code> 有什么问题？</td><td><details><summary aria-label="核对第 18 题">核对</summary>语义未必符合业务预期，例如 nil slice 与空 slice 不等。测试优先使用明确字段比较或适合的比较工具和选项。</details></td></tr><tr><td><span id="q19-为什么-map-value-用-struct-指针不一定更快"></span>Q19：为什么 map value 用 struct 指针不一定更快？</td><td><details><summary aria-label="核对第 19 题">核对</summary>指针减少大结构复制，但增加堆对象、GC 扫描和 cache miss。需要根据大小、修改语义和 benchmark 选择。</details></td></tr><tr><td><span id="q20-字符串可以包含非法-utf-8-吗"></span>Q20：字符串可以包含非法 UTF-8 吗？</td><td><details><summary aria-label="核对第 20 题">核对</summary>可以。string 是任意字节序列；range 遇到非法序列会产生替换 rune。</details></td></tr></tbody></table><h3 id="_28-3-并发类" tabindex="-1">28.3 并发类 <a class="header-anchor" href="#_28-3-并发类" aria-label="Permalink to &quot;28.3 并发类 {#_28-3-并发类}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自测问题</th><th>回看或补充答案</th></tr></thead><tbody><tr><td><span id="q21-goroutine-是并发还是并行"></span>Q21：goroutine 是并发还是并行？</td><td><details><summary aria-label="核对第 21 题">核对</summary>goroutine 提供并发结构；当有多个 P、多个 M 和多个 CPU 核时可以并行执行。</details></td></tr><tr><td><span id="q22-channel-是线程安全的吗"></span>Q22：channel 是线程安全的吗？</td><td><details><summary aria-label="核对第 22 题">核对</summary>channel 的发送、接收和关闭由运行时同步，但围绕它的业务协议仍可能有竞态，例如多个发送者争相关闭。</details></td></tr><tr><td><span id="q23-关闭-channel-后还能读取吗"></span>Q23：关闭 channel 后还能读取吗？</td><td><details><summary aria-label="核对第 23 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-06#_10-3-向-nil、已关闭-channel-操作会怎样">已关闭通道接收</a></details></td></tr><tr><td><span id="q24-如何判断-channel-已关闭"></span>Q24：如何判断 channel 已关闭？</td><td><details><summary aria-label="核对第 24 题">核对</summary>接收时使用 <code>v, ok := &lt;-ch</code>。没有通用无竞争的“先检查是否关闭再发送”操作。</details></td></tr><tr><td><span id="q25-buffered-channel-满了会怎样"></span>Q25：buffered channel 满了会怎样？</td><td><details><summary aria-label="核对第 25 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-06#_10-2-无缓冲和有缓冲-channel-有什么区别">缓冲与阻塞</a></details></td></tr><tr><td><span id="q26-mutex-是否公平"></span>Q26：Mutex 是否公平？</td><td><details><summary aria-label="核对第 26 题">核对</summary>运行时在正常和饥饿模式间权衡吞吐与公平，不能把它当严格 FIFO 锁。</details></td></tr><tr><td><span id="q27-mutex-可以跨-goroutine-解锁吗"></span>Q27：Mutex 可以跨 goroutine 解锁吗？</td><td><details><summary aria-label="核对第 27 题">核对</summary>锁不与特定 goroutine 绑定，技术上可在另一 goroutine 解锁，但这种设计通常难理解，应保持所有权清晰。</details></td></tr><tr><td><span id="q28-waitgroup-可以复用吗"></span>Q28：WaitGroup 可以复用吗？</td><td><details><summary aria-label="核对第 28 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-07#_12-4-sync-waitgroup-怎么用">WaitGroup 阶段边界</a></details></td></tr><tr><td><span id="q29-为什么-add-一般放在-go-语句前"></span>Q29：为什么 <code>Add</code> 一般放在 go 语句前？</td><td><details><summary aria-label="核对第 29 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-07#_12-4-sync-waitgroup-怎么用">Add/Done 时机</a></details></td></tr><tr><td><span id="q30-如何限制-goroutine-数量"></span>Q30：如何限制 goroutine 数量？</td><td><details><summary aria-label="核对第 30 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-16#_29-2-有界并发执行任务">有界任务代码</a></details></td></tr><tr><td><span id="q31-context-取消是否同步等待子-goroutine-退出"></span>Q31：context 取消是否同步等待子 goroutine 退出？</td><td><details><summary aria-label="核对第 31 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-06#_11-4-context-取消会强行杀死-goroutine-吗">取消信号与实际退出</a></details></td></tr><tr><td><span id="q32-select-能保证公平吗"></span>Q32：select 能保证公平吗？</td><td><details><summary aria-label="核对第 32 题">核对</summary>多个就绪 case 中做伪随机选择，减少固定偏置，但不提供业务上的严格公平或优先级保证。</details></td></tr><tr><td><span id="q33-如何实现优先级-channel"></span>Q33：如何实现优先级 channel？</td><td><details><summary aria-label="核对第 33 题">核对</summary>select 本身无严格优先级。可先非阻塞检查高优先级，再进入包含多个 case 的 select，但仍需仔细处理饥饿和竞态；复杂场景用优先队列加协调 goroutine。</details></td></tr><tr><td><span id="q34-什么是死锁"></span>Q34：什么是死锁？</td><td><details><summary aria-label="核对第 34 题">核对</summary>一组执行单元互相等待且没有任何一个能继续。例如锁顺序相反、无接收者发送、等待自己。运行时只能检测部分“所有 goroutine 都睡眠”的情况。</details></td></tr><tr><td><span id="q35-如何避免锁顺序死锁"></span>Q35：如何避免锁顺序死锁？</td><td><details><summary aria-label="核对第 35 题">核对</summary>定义全局锁顺序，所有路径按同一顺序获取；尽量避免嵌套锁；缩小临界区；必要时合并状态所有权。</details></td></tr></tbody></table><h3 id="_28-4-内存与-gc" tabindex="-1">28.4 内存与 GC <a class="header-anchor" href="#_28-4-内存与-gc" aria-label="Permalink to &quot;28.4 内存与 GC {#_28-4-内存与-gc}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自测问题</th><th>回看或补充答案</th></tr></thead><tbody><tr><td><span id="q36-局部变量一定在栈上吗"></span>Q36：局部变量一定在栈上吗？</td><td><details><summary aria-label="核对第 36 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-07#_13-2-什么是逃逸分析">逃逸分析</a></details></td></tr><tr><td><span id="q37-指针一定导致堆分配吗"></span>Q37：指针一定导致堆分配吗？</td><td><details><summary aria-label="核对第 37 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-07#_13-4-new-t-一定在堆上吗">new 与分配位置</a></details></td></tr><tr><td><span id="q38-gc-能回收-goroutine-吗"></span>Q38：GC 能回收 goroutine 吗？</td><td><details><summary aria-label="核对第 38 题">核对</summary>不能像普通不可达对象一样“自动结束”正在阻塞的 goroutine。goroutine 必须执行到返回；其持有对象也可能因此长期存活。 <a href="/programming/go/pro/interview/golang-interview-part-05#_9-8-goroutine-泄漏是什么">goroutine 生命周期</a></details></td></tr><tr><td><span id="q39-减少指针为什么可能降低-gc-成本"></span>Q39：减少指针为什么可能降低 GC 成本？</td><td><details><summary aria-label="核对第 39 题">核对</summary>GC 需要扫描指针图。更紧凑、少指针的数据结构可减少扫描工作并改善 cache locality。 <a href="/programming/go/pro/interview/golang-interview-part-11#_22-3-常见内存优化方向有哪些">数据布局与指针</a></details></td></tr><tr><td><span id="q40-手动调用-runtime-gc-合适吗"></span>Q40：手动调用 <code>runtime.GC()</code> 合适吗？</td><td><details><summary aria-label="核对第 40 题">核对</summary>普通服务通常不合适，运行时会自动调节。只有非常特殊、阶段明确且经过测量的场景才考虑。</details></td></tr><tr><td><span id="q41-gc-时业务会完全停止吗"></span>Q41：GC 时业务会完全停止吗？</td><td><details><summary aria-label="核对第 41 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-08#_14-5-gc-过程中有哪些-stw">STW 与并发标记</a></details></td></tr><tr><td><span id="q42-内存增长一定是泄漏吗"></span>Q42：内存增长一定是泄漏吗？</td><td><details><summary aria-label="核对第 42 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-07#_13-8-为什么进程-rss-不一定在-gc-后立即下降">RSS 与堆趋势</a></details></td></tr><tr><td><span id="q43-怎么区分累计分配和存活内存"></span>Q43：怎么区分累计分配和存活内存？</td><td><details><summary aria-label="核对第 43 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-11#_21-9-heap-profile-中-inuse-和-alloc-的区别">inuse 与 alloc</a></details></td></tr></tbody></table><h3 id="_28-5-网络与数据库" tabindex="-1">28.5 网络与数据库 <a class="header-anchor" href="#_28-5-网络与数据库" aria-label="Permalink to &quot;28.5 网络与数据库 {#_28-5-网络与数据库}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自测问题</th><th>回看或补充答案</th></tr></thead><tbody><tr><td><span id="q44-tcp-为什么可靠"></span>Q44：TCP 为什么可靠？</td><td><details><summary aria-label="核对第 44 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-09#_17-1-tcp-是什么">可靠字节流</a></details></td></tr><tr><td><span id="q45-udp-一定不可靠吗"></span>Q45：UDP 一定不可靠吗？</td><td><details><summary aria-label="核对第 45 题">核对</summary>UDP 本身不保证交付、顺序和去重，但应用层可以在其上构建可靠协议，QUIC 就是典型例子。</details></td></tr><tr><td><span id="q46-keep-alive-的作用是什么"></span>Q46：Keep-Alive 的作用是什么？</td><td><details><summary aria-label="核对第 46 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-09#_17-5-go-http-client-为什么应该复用">连接复用</a></details></td></tr><tr><td><span id="q47-连接池耗尽时会怎样"></span>Q47：连接池耗尽时会怎样？</td><td><details><summary aria-label="核对第 47 题">核对</summary>请求排队等待连接，延迟升高并可能超时。应监控池使用、等待次数/时长，并优化慢查询或调整容量。 <a href="/programming/go/pro/interview/golang-interview-part-10#_19-3-连接池有哪些重要参数">连接池与等待</a></details></td></tr><tr><td><span id="q48-数据库索引为什么能加速查询"></span>Q48：数据库索引为什么能加速查询？</td><td><details><summary aria-label="核对第 48 题">核对</summary>通过有序或特定结构减少扫描数据量，但增加存储和写入维护成本。索引是否生效取决于查询条件、选择性和优化器。</details></td></tr><tr><td><span id="q49-事务越大越好吗"></span>Q49：事务越大越好吗？</td><td><details><summary aria-label="核对第 49 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-10#_19-8-go-中事务怎么写">事务边界</a></details></td></tr><tr><td><span id="q50-先更新-db-再删缓存为什么仍可能不一致"></span>Q50：先更新 DB 再删缓存为什么仍可能不一致？</td><td><details><summary aria-label="核对第 50 题">核对</summary>缓存未命中的读请求可能先读到旧数据库值，在写请求更新数据库并删除缓存后才回填；删除失败也会保留旧缓存。需按一致性要求加入版本校验、重试或补偿。见 <a href="/programming/go/pro/interview/golang-interview-part-10#_20-4-cache-aside-模式是什么">Cache-Aside 读写顺序</a>。</details></td></tr></tbody></table><h3 id="_28-6-工程与微服务" tabindex="-1">28.6 工程与微服务 <a class="header-anchor" href="#_28-6-工程与微服务" aria-label="Permalink to &quot;28.6 工程与微服务 {#_28-6-工程与微服务}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自测问题</th><th>回看或补充答案</th></tr></thead><tbody><tr><td><span id="q51-为什么要传递-trace-id"></span>Q51：为什么要传递 trace ID？</td><td><details><summary aria-label="核对第 51 题">核对</summary>把一次请求跨服务、队列和数据库调用串联起来，便于定位长尾和错误传播。 <a href="/programming/go/pro/interview/golang-interview-part-11#_21-11-如何建立可观测性">跨服务追踪</a></details></td></tr><tr><td><span id="q52-日志中能否直接打印请求体"></span>Q52：日志中能否直接打印请求体？</td><td><details><summary aria-label="核对第 52 题">核对</summary>不应默认打印。可能包含凭证、隐私和大字段；需要字段白名单、脱敏、采样和大小限制。 <a href="/programming/go/pro/interview/golang-interview-part-12#_23-7-日志应该如何设计">日志字段与敏感数据</a></details></td></tr><tr><td><span id="q53-服务出现大量超时应该先增加超时吗"></span>Q53：服务出现大量超时应该先增加超时吗？</td><td><details><summary aria-label="核对第 53 题">核对</summary>不一定。先区分正常业务耗时和过载排队。盲目增加超时会让更多请求占用资源，加重雪崩。</details></td></tr><tr><td><span id="q54-为什么需要背压"></span>Q54：为什么需要背压？</td><td><details><summary aria-label="核对第 54 题">核对</summary>当消费者跟不上生产者时，让上游减速、拒绝或降级，防止无限积压耗尽资源。</details></td></tr><tr><td><span id="q55-什么是隔离舱模式"></span>Q55：什么是隔离舱模式？</td><td><details><summary aria-label="核对第 55 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-13#_25-11-如何防止雪崩">资源隔离</a></details></td></tr><tr><td><span id="q56-配置热更新如何保证并发安全"></span>Q56：配置热更新如何保证并发安全？</td><td><details><summary aria-label="核对第 56 题">核对</summary>构建完整不可变配置快照，校验成功后用 <code>atomic.Value</code> 或锁整体替换；读取方只读取，不修改。 <a href="/programming/go/pro/interview/golang-interview-part-07#_12-9-atomic-value-有什么注意事项">不可变快照发布</a></details></td></tr><tr><td><span id="q57-为什么接口重试必须考虑幂等"></span>Q57：为什么接口重试必须考虑幂等？</td><td><details><summary aria-label="核对第 57 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-12#_24-7-重试应该放在哪一层">重试前提</a></details></td></tr><tr><td><span id="q58-什么时候应该拆微服务"></span>Q58：什么时候应该拆微服务？</td><td><details><summary aria-label="核对第 58 题">核对</summary><a href="/programming/go/pro/interview/golang-interview-part-12#_24-1-微服务的优缺点是什么">拆分收益与代价</a></details></td></tr><tr><td><span id="q59-什么时候使用消息队列"></span>Q59：什么时候使用消息队列？</td><td><details><summary aria-label="核对第 59 题">核对</summary>异步解耦、削峰、事件广播、耗时任务、最终一致性。不要仅为“架构高级”引入。</details></td></tr><tr><td><span id="q60-灰度发布要观察什么"></span>Q60：灰度发布要观察什么？</td><td><details><summary aria-label="核对第 60 题">核对</summary>错误率、延迟分位数、资源、业务指标、依赖影响、日志异常，并保留快速回滚能力。</details></td></tr></tbody></table><hr><h2 id="_29-手写题与代码模板" tabindex="-1">29. 手写题与代码模板 <a class="header-anchor" href="#_29-手写题与代码模板" aria-label="Permalink to &quot;29. 手写题与代码模板 {#_29-手写题与代码模板}&quot;">​</a></h2><h3 id="_29-1-并发安全单例" tabindex="-1">29.1 并发安全单例 <a class="header-anchor" href="#_29-1-并发安全单例" aria-label="Permalink to &quot;29.1 并发安全单例 {#_29-1-并发安全单例}&quot;">​</a></h3><p>自测：两个 goroutine 第一次同时请求同一个客户端，第二个调用何时能安全读取初始化结果？<code>sync.Once</code> 同步初始化并使结果对后续调用者可见。如果构造失败后必须重试，单次初始化的合同便不适用。对照<a href="/programming/go/pro/interview/golang-interview-part-16#initialization-template">初始化模板</a>，再决定是否在程序启动时直接构造并注入依赖。</p>',20)])])}const c=t(d,[["render",n]]);export{u as __pageData,c as default};
